-- -- indexes -----------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_production_bom_items_bom_id ON public.production_bom_items USING btree (bom_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_production_boms_finished_product ON public.production_boms USING btree (finished_product_id);
CREATE INDEX IF NOT EXISTS idx_production_expenses_finance_expense ON public.production_expenses USING btree (finance_expense_id) WHERE (finance_expense_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_production_expenses_finance_tx ON public.production_expenses USING btree (finance_transaction_id) WHERE (finance_transaction_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_production_expenses_order ON public.production_expenses USING btree (production_order_id);
CREATE INDEX IF NOT EXISTS idx_production_expenses_order_id ON public.production_expenses USING btree (production_order_id);
CREATE INDEX IF NOT EXISTS idx_production_materials_order_id ON public.production_materials USING btree (production_order_id);
CREATE INDEX IF NOT EXISTS idx_production_materials_product ON public.production_materials USING btree (product_id);
CREATE INDEX IF NOT EXISTS idx_production_materials_warehouse ON public.production_materials USING btree (warehouse_id);
CREATE INDEX IF NOT EXISTS idx_production_orders_advance_tx ON public.production_orders USING btree (advance_transaction_id) WHERE (advance_transaction_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_production_orders_contractor_id ON public.production_orders USING btree (contractor_id);
CREATE INDEX IF NOT EXISTS idx_production_orders_created_at ON public.production_orders USING btree (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_production_orders_customer ON public.production_orders USING btree (customer_id);
CREATE INDEX IF NOT EXISTS idx_production_orders_customer_id ON public.production_orders USING btree (customer_id);
CREATE INDEX IF NOT EXISTS idx_production_orders_ousta ON public.production_orders USING btree (ousta_id);
CREATE INDEX IF NOT EXISTS idx_production_orders_production_model ON public.production_orders USING btree (production_model);
CREATE INDEX IF NOT EXISTS idx_production_orders_production_type ON public.production_orders USING btree (production_type);
CREATE INDEX IF NOT EXISTS idx_production_orders_sale ON public.production_orders USING btree (sale_id);
CREATE INDEX IF NOT EXISTS idx_production_orders_status ON public.production_orders USING btree (status);
CREATE INDEX IF NOT EXISTS idx_production_orders_subcontractor ON public.production_orders USING btree (subcontractor_id);
CREATE INDEX IF NOT EXISTS idx_production_orders_type ON public.production_orders USING btree (type);
CREATE INDEX IF NOT EXISTS idx_production_stock_reservations_open ON public.production_stock_reservations USING btree (product_id, warehouse_id) WHERE (status = 'reserved'::text);
CREATE INDEX IF NOT EXISTS idx_production_stock_reservations_order ON public.production_stock_reservations USING btree (production_order_id);

-- -- triggers ----------------------------------------------------
CREATE OR REPLACE TRIGGER trg_audit_production_contractors AFTER DELETE OR UPDATE ON public.production_contractors FOR EACH ROW EXECUTE FUNCTION public.audit_log_row_change('PRODUCTION');
CREATE OR REPLACE TRIGGER trg_audit_production_expenses AFTER INSERT OR DELETE OR UPDATE ON public.production_expenses FOR EACH ROW EXECUTE FUNCTION public.audit_log_row_change('PRODUCTION');
CREATE OR REPLACE TRIGGER trg_production_expenses_sync_ledger AFTER INSERT OR DELETE ON public.production_expenses FOR EACH ROW EXECUTE FUNCTION public.sync_production_expense_to_ledger();
CREATE OR REPLACE TRIGGER trg_audit_production_materials AFTER DELETE OR UPDATE ON public.production_materials FOR EACH ROW EXECUTE FUNCTION public.audit_log_row_change('PRODUCTION');
CREATE OR REPLACE TRIGGER production_orders_delivery_slip AFTER UPDATE OF status ON public.production_orders FOR EACH ROW EXECUTE FUNCTION public.trg_production_orders_delivery_slip();
CREATE OR REPLACE TRIGGER trg_audit_production_orders AFTER UPDATE ON public.production_orders FOR EACH ROW WHEN (((old.total_project_price IS DISTINCT FROM new.total_project_price) OR (old.remaining_balance IS DISTINCT FROM new.remaining_balance) OR (old.advance_payment IS DISTINCT FROM new.advance_payment) OR (old.installation_fee IS DISTINCT FROM new.installation_fee) OR (old.contractor_fee IS DISTINCT FROM new.contractor_fee) OR (old.subcontractor_fee_amount IS DISTINCT FROM new.subcontractor_fee_amount) OR (old.subcontractor_fee_percent IS DISTINCT FROM new.subcontractor_fee_percent) OR (old.additional_cost IS DISTINCT FROM new.additional_cost) OR (old.additional_expenses_total IS DISTINCT FROM new.additional_expenses_total) OR (old.total_cost IS DISTINCT FROM new.total_cost) OR (old.total_expense_cost IS DISTINCT FROM new.total_expense_cost) OR (old.total_material_cost IS DISTINCT FROM new.total_material_cost) OR (old.total_outsourcing_cost IS DISTINCT FROM new.total_outsourcing_cost) OR (old.net_profit IS DISTINCT FROM new.net_profit) OR (old.profit_margin IS DISTINCT FROM new.profit_margin))) EXECUTE FUNCTION public.audit_log_row_change('PRODUCTION');
CREATE OR REPLACE TRIGGER trg_audit_production_outsourcing AFTER DELETE OR UPDATE ON public.production_outsourcing FOR EACH ROW EXECUTE FUNCTION public.audit_log_row_change('PRODUCTION');

